#!/usr/bin/env python3
"""Build book 12 without changing the original storyboard or illustrations."""
import argparse,hashlib,json,re
from pathlib import Path
from html import escape as esc
from PIL import Image
from lxml import html
ROOT=Path(__file__).resolve().parents[1];DOCS=ROOT/'docs/four-jhanas';SITE=ROOT/'four-jhanas'
TABLE={'columns':['初禪','第二禪','第三禪','第四禪'],'rows':[['進一步放下','欲、惡不善法','覺、觀','喜','苦、樂'],['心的狀態','有覺、有觀','內淨一心','捨、正念正知','捨淨念、一心'],['感受','離生喜樂','定生喜樂','離喜而樂','不苦不樂']]}
def seconds(value):
 m,s=map(int,value.split(':'));return m*60+s
def validate():
 receipt=json.loads((DOCS/'receipt.json').read_text())
 for name,row in receipt['originalFiles'].items():
  raw=(DOCS/name).read_bytes();assert len(raw)==row['bytes'] and hashlib.sha256(raw).hexdigest()==row['sha256'],name
 for line in (DOCS/'SHA256SUMS').read_text().splitlines():
  digest,name=line.split('  ',1);assert hashlib.sha256((DOCS/name).read_bytes()).hexdigest()==digest,name
 story=json.loads((DOCS/'storyboard.json').read_text());assert [s['id'] for s in story]==[f'S{i:02}' for i in range(1,11)]
 cues=[c for s in story for c in s['cues']];assert [c['id'] for c in cues]==[f'P{i:03}' for i in range(1,131)]
 assert all(seconds(c['end'])>seconds(c['start']) for c in cues)
 assert all(cues[i]['end']==cues[i+1]['start'] for i in range(129))
 assert story[7]['asset'].endswith('9A373B0F-ECD4-4060-971F-47B1ED7DDFEF.jpeg')
 assert story[8]['asset'].endswith('3A1C9428-025F-40E8-8A5C-0E400BAE3862.jpeg')
 print('Original hashes, 10 scenes and P001–P130 continuity passed')
def book():
 story=json.loads((DOCS/'storyboard.json').read_text());catalog=json.loads((DOCS/'scripture-catalog.json').read_text());labels=json.loads((DOCS/'overlay-layout.json').read_text())['overlays'];plan=json.loads((DOCS/'reader-plan.json').read_text());scenes=[];pages=[];focus={}
 preparation={'S01':('戒','dn2-precept'),'S02':('守護根門','dn2-senses'),'S03':('正念正知','dn2-awareness'),'S04':('知足與鳥翼譬喻','dn2-contentment'),'S05':('五蓋','dn2-hindrances')}
 edges={'S06':[0,24.880,49.701,75.120,100],'S07':[0,24.940,50.179,72.309,100],'S08':[0,24.609,50.065,74.479,100],'S09':[0,24.674,49.740,74.674,100]}
 for scene in story:
  sid=scene['id']
  with Image.open(DOCS/scene['asset']) as im:dimensions=list(im.size)
  scenes.append({'id':sid,'title':scene['title'],'image':scene['asset'],'alt':scene['title'],'dimensions':dimensions,'start':len(pages),'artOverlay':labels[sid],'summaryRows':[],'overlaySpecification':scene['overlay']})
  for local,(cue,mapping) in enumerate(zip(scene['cues'],plan[sid]),1):
   assert cue['id']==mapping['paragraphId']
   context=('《長部》第二經〈沙門果經〉 · '+preparation[sid][0]) if sid in preparation else None
   if sid=='S05':context+='：貪欲、瞋恚、昏沉睡眠、掉舉追悔、疑'
   pages.append({'scene':sid,'title':scene['title'],'paragraphId':cue['id'],'paragraphNumber':local,'startTime':cue['start'],'endTime':cue['end'],'startSeconds':seconds(cue['start']),'endSeconds':seconds(cue['end']),'videoUrl':'https://www.youtube.com/watch?v=cNXY6hsxn6o&t='+str(seconds(cue['start']))+'s','lines':[cue['text']],'quotes':[catalog[q] for q in mapping['quoteIds']],'sourceNote':None,'context':context,'sourceAnchor':preparation[sid][1] if sid in preparation else None,'image':'../assets/'+sid+'.webp','dimensions':dimensions,'tableSummary':TABLE if sid=='S10' else None})
  if sid in edges:
   e=edges[sid];focus[sid]={'panels':[{'id':f'p{i+1}','label':f'第{i+1}格','x':e[i],'y':0,'width':e[i+1]-e[i],'height':100} for i in range(4)],'pages':[p['panel'] for p in plan[sid]],'note':'原圖四欄由左至右；有【第幾格】的段落聚焦該格，開頭與收束回全幅。'}
 pages.append({'scene':'S10','title':'閱讀說明','paragraphNumber':8,'lines':[],'quotes':[],'sourceNote':None,'context':None,'image':None,'dimensions':None,'afterword':True,'textSummary':[{'title':'經典依據','paragraphs':['本繪本依《長部》第二經〈沙門果經〉與《雜阿含經》第483經製作。圖中的小貓、呼吸與落葉是故事譬喻，解讀仍請以原經文為準。','也希望這本繪本能成為您走入經藏的起點。'],'rows':[]}]})
 data={'title':'四禪','video':{'url':'https://youtu.be/cNXY6hsxn6o','durationSeconds':742.57,'included':False},'timingAccuracy':'approximate_1_to_3_seconds_not_audio_verified','scenes':scenes,'pages':pages}
 return {SITE/'book/book-data.js':'// Generated by scripts/build-four-jhanas.py; original handoff preserved.\nconst BOOK = '+json.dumps(data,ensure_ascii=False,indent=2)+';\n',SITE/'book/panel-focus-data.js':'// Vertical panel boundaries measured on complete original images.\nconst PANEL_FOCUS = '+json.dumps({'coordinateBasis':'displayed-image-percent','scenes':focus},ensure_ascii=False,indent=2)+';\n'}
def guide():
 sources=json.loads((DOCS/'verified-sources.json').read_text())['sources'];template=html.parse(str(ROOT/'anapana/index.html'));icons=[html.tostring(x,encoding='unicode') for x in template.xpath('//article[@id="sa803"]//a[contains(@class,"source-button")]/svg')]
 def button(url,label,kind,i):return '<a class="source-button source-button--'+kind+'" href="'+esc(url,quote=True)+'" target="_blank" rel="noopener noreferrer">'+icons[i]+'<span>'+label+'</span></a>'
 text='''<!doctype html><html lang="zh-Hant-TW"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>四禪｜SutraZen 主題導讀</title><meta name="description" content="從戒、護根到初禪、第二禪、第三禪與第四禪，閱讀十幕完整繪本，對讀沙門果經及雜阿含483經。"><link rel="stylesheet" href="guide.css"><link rel="stylesheet" href="../guide-header.css"><link rel="stylesheet" href="../guide-ui.css"></head><body class="topic-guide"><header class="guide-header"><div class="guide-header-inner"><span class="guide-brand">SutraZen</span><a class="guide-return" href="../index.html">回三十七道品修道地圖</a></div></header><main class="wrap guide-content"><p class="eyebrow">佛法繪本 · 主題導讀</p><h1>四禪</h1><p class="lead"><strong>從清淨生活開始，看心如何一層一層安定下來。</strong>跟著小貓，經過持戒、守護六根、正念正知、少欲知足與斷五蓋，再對讀四禪的定義及沐浴粉團、湧泉池、蓮池與白衣裹身四個譬喻。</p>
<section class="book-preview" aria-labelledby="book-heading"><h2 id="book-heading">翻頁繪本 · 四禪篇</h2><p class="intro">一頁一頁閱讀完整故事，對照插畫與經文。</p><a class="book-cover" href="book/index.html" aria-label="開始翻閱四禪"><img src="assets/S06.webp" width="1672" height="941" alt="初禪四格插畫與沐浴粉團譬喻"><span class="book-cover-action"><span>開始翻閱 →</span></span></a></section>
<section><h2>從準備到四禪</h2><div class="chapter-grid">'''
 for sid,title,copy in [('S01','禪定以前','持戒、護根、正念正知、知足與斷五蓋。'),('S06','初禪','離欲、離惡不善法，有覺有觀，離生喜樂。'),('S07','第二禪','覺、觀平息，內淨一心，定生喜樂。'),('S08','第三禪','離喜、貪，捨心，住正念、正知。'),('S09','第四禪','離苦息樂，憂喜先已離，不苦不樂。'),('S10','四禪總結','對照逐步放下、心的狀態與感受。')]:text+='<a href="book/index.html?scene='+sid+'"><strong>'+title+'</strong><span>'+copy+'</span></a>'
 text+='</div></section><section><h2>四禪比較</h2><div class="table-wrap"><table><thead><tr><th scope="col">項目</th>'+''.join('<th scope="col">'+x+'</th>' for x in TABLE['columns'])+'</tr></thead><tbody>'
 for row in TABLE['rows']:text+='<tr><th scope="row">'+row[0]+'</th>'+''.join('<td>'+x+'</td>' for x in row[1:])+'</tr>'
 text+='''</tbody></table></div></section><section id="video" class="guide-video"><h2>療癒系佛法繪本 · 四禪篇</h2><div class="video"><iframe title="療癒系佛法繪本 · 四禪篇" src="https://www.youtube.com/embed/cNXY6hsxn6o" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe></div></section><section id="sources" class="refs" aria-labelledby="sources-heading"><h2 id="sources-heading">閱讀原經｜經典出處與原文對讀</h2>'''
 for source in sources:
  classical=source['id']=='sa483';text+='<article class="source-entry" id="'+source['id']+'">'+''.join('<span class="source-anchor" id="'+q+'"></span>' for q in source['quoteIds'])+'<p class="eyebrow">四禪 · 經典出處</p><h3>'+source['title']+'</h3><p class="source-meta">'+source['meta']+'</p><div class="source-actions">'+button(source['primary'],'漢譯經文' if classical else '中譯經文','original',0)+button(source['comparison'],source['comparisonLabel'],'annotation',1)+'</div><div class="source-providers">'+''.join('<p>'+esc(p)+'</p>' for p in source['providers'])+'</div><div class="source-text">'
  for section in source['sections']:text+='<h4 class="source-text-heading" id="'+section['id']+'">'+section['title']+'</h4><blockquote><p>'+esc(section['text'])+'</p></blockquote>'
  text+='</div></article>'
 return SITE/'index.html',text+'</section></main></body></html>\n'
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--check',action='store_true');a=p.parse_args();validate();outputs=book();path,body=guide();outputs[path]=body
 for path,body in outputs.items():
  if a.check:assert path.read_text()==body,path
  else:path.write_text(body)
 print('10 scenes / 130 unchanged timed captions / 8 scripture cards / 7 image overlays / 131 pages including editorial ending')
